package servicos;
import java.util.Calendar; import java.util.Date; import model.*;
public class RelatoriosService { public ResumoFinanceiro resumoMensal(int mes,int ano){FiltroDespesa d=new FiltroDespesa();FiltroReceita r=new FiltroReceita();Calendar i=Calendar.getInstance();i.clear();i.set(ano,mes,1);Calendar f=(Calendar)i.clone();f.add(Calendar.MONTH,1);f.add(Calendar.DAY_OF_MONTH,-1);d.inicio=r.inicio=i.getTime();d.fim=r.fim=f.getTime();ResumoFinanceiro x=new ResumoFinanceiro();DespesaService ds=new DespesaService();for(entidades.Receita receita:new ReceitaService().listar(r))x.setReceitas(x.getReceitas()+(receita.getValor()==null?0:receita.getValor()));for(entidades.Despesa despesa:ds.listar(d)){double v=despesa.getValor()==null?0:despesa.getValor();x.setDespesas(x.getDespesas()+v);StatusDespesa s=ds.calcularStatus(despesa);if(s==StatusDespesa.PAGO)x.setPagas(x.getPagas()+v);else if(s==StatusDespesa.ATRASADA)x.setAtrasadas(x.getAtrasadas()+v);else x.setPendentes(x.getPendentes()+v);}x.setSaldo(x.getReceitas()-x.getDespesas());return x;}}
